# Copyright (c) 2026
"""Snapshot-bound inventory of native lexical and direct structural retrieval."""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar

if TYPE_CHECKING:
    from devtools.context.repository.resource import (
        RepositoryResourceAddress,
        RepositoryResourceOccurrence,
    )
    from devtools.context.repository.snapshot import (
        RepositorySnapshot,
        RepositorySnapshotId,
    )
    from devtools.context.retrieval.lexical.bm25 import (
        RepositoryTextLexicalBm25Match,
        RepositoryTextLexicalBm25RetrievalResult,
    )
    from devtools.context.retrieval.structural import (
        PythonDirectStructuralResourceEvidence,
        PythonDirectStructuralRetrievalResult,
    )


@dataclass(frozen=True, slots=True)
class LexicalStructuralResourceEntry:
    """Correlate native supports for one resource in one explicit snapshot."""

    snapshot_id: RepositorySnapshotId
    resource: RepositoryResourceOccurrence
    lexical_rank: int | None
    lexical_match: RepositoryTextLexicalBm25Match | None
    structural_supports: tuple[PythonDirectStructuralResourceEvidence, ...]


@dataclass(frozen=True, slots=True)
class LexicalStructuralResourceInventory:
    """Retain a purpose and both native retrieval results without selection."""

    snapshot_id: RepositorySnapshotId
    purpose: str
    lexical_result: RepositoryTextLexicalBm25RetrievalResult
    structural_result: PythonDirectStructuralRetrievalResult
    resources: tuple[LexicalStructuralResourceEntry, ...]

    COMPOSITION_SEMANTICS: ClassVar[str] = (
        "snapshot-bound-lexical-direct-structural-resource-inventory-v1"
    )


def compose_lexical_structural_resource_evidence(  # noqa: C901, PLR0912
    snapshot: RepositorySnapshot,
    *,
    purpose: str,
    lexical_result: RepositoryTextLexicalBm25RetrievalResult,
    structural_result: PythonDirectStructuralRetrievalResult,
) -> LexicalStructuralResourceInventory:
    """Correlate native matches and supports under one caller-owned invocation.

    Address order is a neutral inventory order, not a relevance ranking. The
    lexical query remains mechanism input and need not equal the purpose.
    """
    if not purpose.strip():
        msg = "Resource evidence composition requires a nonempty purpose."
        raise ValueError(msg)
    if structural_result.snapshot_id != snapshot.id or (
        structural_result.request.purpose != purpose
    ):
        msg = "Structural retrieval differs from the composition snapshot or purpose."
        raise ValueError(msg)

    collection = (
        lexical_result.index.corpus_statistics.collection_analysis.document_collection
    )
    if collection.corpus.definition.discovery.repository_id != snapshot.repository_id:
        msg = "Lexical corpus belongs to another repository."
        raise ValueError(msg)
    if collection.corpus.resources != tuple(
        document.resource for document in collection.documents
    ):
        msg = "Lexical documents differ from their observed corpus."
        raise ValueError(msg)
    for document in collection.documents:
        if document.repository_id != snapshot.repository_id:
            msg = "Lexical document belongs to another repository."
            raise ValueError(msg)
        _require_snapshot_resource(snapshot, document.resource)

    statistics = lexical_result.index.corpus_statistics.document_statistics
    if tuple(item.analysis.document for item in statistics) != collection.documents:
        msg = "Lexical index statistics differ from its document collection."
        raise ValueError(msg)

    lexical_by_address: dict[
        RepositoryResourceAddress, tuple[int, RepositoryTextLexicalBm25Match],
    ] = {}
    for rank, match in enumerate(lexical_result.matches, start=1):
        if not any(match.document_statistics is item for item in statistics):
            msg = "Lexical match is absent from its retrieval index."
            raise ValueError(msg)
        address = match.document_statistics.analysis.document.resource.address
        previous = lexical_by_address.get(address)
        if previous is not None and previous[1] != match:
            msg = "Lexical retrieval has conflicting matches for one resource."
            raise ValueError(msg)
        if previous is None:
            lexical_by_address[address] = (rank, match)

    structural_by_address: dict[
        RepositoryResourceAddress, list[PythonDirectStructuralResourceEvidence],
    ] = {}
    structural_seen: dict[
        RepositoryResourceAddress, set[tuple[RepositoryResourceAddress, str, str]],
    ] = {}
    for candidate in structural_result.candidates:
        if candidate.snapshot_id != snapshot.id:
            msg = "Structural candidate belongs to another snapshot."
            raise ValueError(msg)
        snapshot.resource_at(candidate.resource_address)
        for support in candidate.supports:
            key = (support.seed_resource, support.direction, support.fact.identity)
            seen = structural_seen.setdefault(candidate.resource_address, set())
            if key not in seen:
                seen.add(key)
                structural_by_address.setdefault(candidate.resource_address, []).append(
                    support,
                )

    addresses = sorted(
        lexical_by_address.keys() | structural_by_address.keys(),
        key=str,
    )
    resources: list[LexicalStructuralResourceEntry] = []
    for address in addresses:
        lexical = lexical_by_address.get(address)
        resources.append(
            LexicalStructuralResourceEntry(
                snapshot_id=snapshot.id,
                resource=snapshot.resource_at(address),
                lexical_rank=lexical[0] if lexical is not None else None,
                lexical_match=lexical[1] if lexical is not None else None,
                structural_supports=tuple(structural_by_address.get(address, ())),
            ),
        )
    return LexicalStructuralResourceInventory(
        snapshot_id=snapshot.id,
        purpose=purpose,
        lexical_result=lexical_result,
        structural_result=structural_result,
        resources=tuple(resources),
    )


def _require_snapshot_resource(
    snapshot: RepositorySnapshot,
    resource: RepositoryResourceOccurrence,
) -> None:
    try:
        current = snapshot.resource_at(resource.address)
    except ValueError as error:
        msg = "Lexical corpus resource is absent from the supplied snapshot."
        raise ValueError(msg) from error
    if current != resource:
        msg = "Lexical corpus resource differs from the supplied snapshot."
        raise ValueError(msg)

# Copyright (c) 2026
"""Direct, purpose-relative resource projection over established Python RI facts."""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar, Literal

from devtools.context.python.imports.relations import PythonResolvedModuleImportRelation
from devtools.context.python.modules.membership import PythonImmediatePackageMembership
from devtools.context.python.references.analysis import PythonFunctionReferenceKnowledge

if TYPE_CHECKING:
    from collections.abc import Sequence

    from devtools.context.repository.resource import (
        RepositoryResourceAddress,
        RepositoryResourceOccurrence,
    )
    from devtools.context.repository.snapshot import (
        RepositorySnapshot,
        RepositorySnapshotId,
    )

type PythonDirectStructuralFact = (
    PythonResolvedModuleImportRelation
    | PythonFunctionReferenceKnowledge
    | PythonImmediatePackageMembership
)
type PythonDirectStructuralDirection = Literal[
    "import-to-target",
    "import-to-source",
    "reference-to-definition",
    "definition-to-reference",
    "child-to-package",
    "package-to-child",
]


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralRetrievalRequest:
    """Carry one information purpose and caller-selected resource anchors."""

    purpose: str
    seed_resources: tuple[RepositoryResourceAddress, ...]

    def __post_init__(self) -> None:
        """Require an explicit purpose and a nonempty, distinct seed set."""
        if not self.purpose.strip():
            msg = "Direct structural retrieval requires a nonempty purpose."
            raise ValueError(msg)
        if not self.seed_resources or len(set(self.seed_resources)) != len(
            self.seed_resources,
        ):
            msg = "Direct structural retrieval requires distinct seed resources."
            raise ValueError(msg)


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralResourceEvidence:
    """Retain one seed, direction, and exact RI fact supporting a resource."""

    seed_resource: RepositoryResourceAddress
    direction: PythonDirectStructuralDirection
    fact: PythonDirectStructuralFact

    MECHANISM: ClassVar[str] = "direct-python-ri-resource-projection-v1"


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralResourceCandidate:
    """Group independent direct supports for one snapshot resource occurrence."""

    snapshot_id: RepositorySnapshotId
    resource_address: RepositoryResourceAddress
    supports: tuple[PythonDirectStructuralResourceEvidence, ...]


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralRetrievalResult:
    """Retain the request, snapshot, and candidates in first-support order."""

    request: PythonDirectStructuralRetrievalRequest
    snapshot_id: RepositorySnapshotId
    candidates: tuple[PythonDirectStructuralResourceCandidate, ...]


def retrieve_python_direct_structural_resources(  # noqa: C901, PLR0912
    snapshot: RepositorySnapshot,
    *,
    request: PythonDirectStructuralRetrievalRequest,
    imports: Sequence[PythonResolvedModuleImportRelation] = (),
    references: Sequence[PythonFunctionReferenceKnowledge] = (),
    memberships: Sequence[PythonImmediatePackageMembership] = (),
) -> PythonDirectStructuralRetrievalResult:
    """Project supplied positive RI facts one relation away from each seed.

    Inputs are already-derived facts. Missing facts establish no negative claim;
    this operation neither derives relations nor selects or ranks candidates.
    """
    for seed in request.seed_resources:
        snapshot.resource_at(seed)

    pairs: list[
        tuple[
            RepositoryResourceAddress,
            RepositoryResourceAddress,
            PythonDirectStructuralDirection,
            PythonDirectStructuralDirection,
            PythonDirectStructuralFact,
        ]
    ] = []
    for import_fact in imports:
        if not isinstance(import_fact, PythonResolvedModuleImportRelation):
            msg = "Imports must contain resolved module import relations."
            raise TypeError(msg)
        _check_endpoint(
            snapshot, import_fact.source.snapshot_id, import_fact.source.resource,
        )
        _check_endpoint(
            snapshot, import_fact.target.snapshot_id, import_fact.target.resource,
        )
        pairs.append(
            (
                import_fact.source.resource.address,
                import_fact.target.resource.address,
                "import-to-target",
                "import-to-source",
                import_fact,
            ),
        )
    for reference_fact in references:
        if not isinstance(reference_fact, PythonFunctionReferenceKnowledge):
            msg = "References must contain qualified function reference knowledge."
            raise TypeError(msg)
        reference_source = reference_fact.occurrence
        definition = reference_fact.target_declaration.support
        _check_address(
            snapshot, reference_source.snapshot_id, reference_source.resource_address,
        )
        _check_address(snapshot, definition.snapshot_id, definition.resource_address)
        pairs.append(
            (
                reference_source.resource_address,
                definition.resource_address,
                "reference-to-definition",
                "definition-to-reference",
                reference_fact,
            ),
        )
    for membership_fact in memberships:
        if not isinstance(membership_fact, PythonImmediatePackageMembership):
            msg = "Memberships must contain immediate package membership facts."
            raise TypeError(msg)
        _check_endpoint(
            snapshot, membership_fact.child.snapshot_id, membership_fact.child.resource,
        )
        _check_endpoint(
            snapshot,
            membership_fact.package.snapshot_id,
            membership_fact.package.resource,
        )
        pairs.append(
            (
                membership_fact.child.resource.address,
                membership_fact.package.resource.address,
                "child-to-package",
                "package-to-child",
                membership_fact,
            ),
        )

    grouped: dict[
        RepositoryResourceAddress,
        list[PythonDirectStructuralResourceEvidence],
    ] = {}
    seen: set[
        tuple[RepositoryResourceAddress, PythonDirectStructuralDirection, str]
    ] = set()
    for seed in request.seed_resources:
        for source_address, target_address, forward, reverse, fact in pairs:
            if source_address == target_address:
                continue
            if seed == source_address:
                candidate, direction = target_address, forward
            elif seed == target_address:
                candidate, direction = source_address, reverse
            else:
                continue
            key = (seed, direction, fact.identity)
            if key not in seen:
                seen.add(key)
                grouped.setdefault(candidate, []).append(
                    PythonDirectStructuralResourceEvidence(seed, direction, fact),
                )
    return PythonDirectStructuralRetrievalResult(
        request=request,
        snapshot_id=snapshot.id,
        candidates=tuple(
            PythonDirectStructuralResourceCandidate(
                snapshot.id,
                address,
                tuple(supports),
            )
            for address, supports in grouped.items()
        ),
    )


def _check_endpoint(
    snapshot: RepositorySnapshot,
    snapshot_id: RepositorySnapshotId,
    resource: RepositoryResourceOccurrence,
) -> None:
    if snapshot_id != snapshot.id or snapshot.resource_at(resource.address) != resource:
        msg = "Structural fact endpoint does not belong to the supplied snapshot."
        raise ValueError(msg)


def _check_address(
    snapshot: RepositorySnapshot,
    snapshot_id: RepositorySnapshotId,
    address: RepositoryResourceAddress,
) -> None:
    if snapshot_id != snapshot.id:
        msg = "Structural fact endpoint does not belong to the supplied snapshot."
        raise ValueError(msg)
    snapshot.resource_at(address)

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar

from devtools.context.retrieval.lexical.analysis import iter_lexical_spans
from devtools.context.retrieval.lexical.filename import (
    build_repository_text_filename_lexical_index,
    score_repository_text_filename_lexical_bm25,
)
from devtools.context.retrieval.lexical.scoring import (
    calculate_bm25_inverse_document_frequency,
    calculate_bm25_term_contribution,
)

if TYPE_CHECKING:
    from devtools.context.retrieval.lexical.filename import (
        RepositoryTextFilenameLexicalBm25TermContribution,
        RepositoryTextFilenameLexicalIndex,
    )
    from devtools.context.retrieval.lexical.index import (
        RepositoryTextLexicalInvertedIndex,
    )
    from devtools.context.retrieval.lexical.statistics import (
        RepositoryTextLexicalDocumentStatistics,
    )


@dataclass(frozen=True, slots=True)
class RepositoryTextLexicalQueryObservation:
    """Record one exact lexical span observed in retrieval query text."""

    encounter_ordinal: int
    observed_text: str
    normalized_term: str
    start: int
    end: int


@dataclass(frozen=True, slots=True)
class RepositoryTextLexicalQuery:
    """Retain query text and baseline lexical observations for BM25 retrieval."""

    text: str
    observations: tuple[RepositoryTextLexicalQueryObservation, ...]

    QUERY_SEMANTICS: ClassVar[str] = "unicode-word-span-casefold-v1"

    @property
    def normalized_terms(self) -> tuple[str, ...]:
        """Return distinct normalized query terms in first encounter order."""
        return tuple(
            dict.fromkeys(
                observation.normalized_term for observation in self.observations
            ),
        )


@dataclass(frozen=True, slots=True)
class RepositoryTextLexicalBm25Settings:
    """Configure one bounded Okapi BM25 retrieval realization."""

    k1: float = 1.2
    b: float = 0.75

    def __post_init__(self) -> None:
        """Validate finite BM25 saturation and length-normalization parameters."""
        if not math.isfinite(self.k1) or self.k1 < 0:
            msg = "BM25 k1 must be finite and greater than or equal to zero."
            raise ValueError(msg)
        if not math.isfinite(self.b) or not 0 <= self.b <= 1:
            msg = "BM25 b must be finite and between zero and one."
            raise ValueError(msg)


_DEFAULT_BM25_SETTINGS = RepositoryTextLexicalBm25Settings()
_FILENAME_BM25_WEIGHT = 0.25


@dataclass(frozen=True, slots=True)
class RepositoryTextLexicalBm25TermContribution:
    """Explain one normalized query term's contribution to a document score."""

    normalized_term: str
    term_frequency: int
    document_frequency: int
    inverse_document_frequency: float
    document_length: int
    average_document_length: float
    contribution: float


@dataclass(frozen=True, slots=True)
class RepositoryTextLexicalBm25Match:
    """Retain one positively scored document and its local BM25 evidence."""

    document_statistics: RepositoryTextLexicalDocumentStatistics
    score: float
    term_contributions: tuple[RepositoryTextLexicalBm25TermContribution, ...]
    content_score: float = 0.0
    filename_score: float = 0.0
    filename_weight: float = 0.0
    weighted_filename_score: float = 0.0
    filename_term_contributions: tuple[
        RepositoryTextFilenameLexicalBm25TermContribution,
        ...,
    ] = ()


@dataclass(frozen=True, slots=True)
class RepositoryTextLexicalBm25RetrievalResult:
    """Retain bounded ranked BM25 matches for one query and lexical index."""

    query: RepositoryTextLexicalQuery
    index: RepositoryTextLexicalInvertedIndex
    settings: RepositoryTextLexicalBm25Settings
    maximum_results: int
    matches: tuple[RepositoryTextLexicalBm25Match, ...]
    filename_index: RepositoryTextFilenameLexicalIndex | None = None

    RETRIEVAL_SEMANTICS: ClassVar[str] = "okapi-bm25-distinct-query-terms-v1"


def analyze_repository_text_lexical_query(
    *,
    text: str,
) -> RepositoryTextLexicalQuery:
    """Analyze query text using the exact baseline document lexical semantics."""
    return RepositoryTextLexicalQuery(
        text=text,
        observations=tuple(
            RepositoryTextLexicalQueryObservation(
                encounter_ordinal=ordinal,
                observed_text=observed_text,
                normalized_term=normalized_term,
                start=start,
                end=end,
            )
            for ordinal, (observed_text, normalized_term, start, end) in enumerate(
                iter_lexical_spans(text=text),
            )
        ),
    )


def retrieve_repository_text_documents_by_content_bm25(
    *,
    query: RepositoryTextLexicalQuery,
    index: RepositoryTextLexicalInvertedIndex,
    maximum_results: int,
    settings: RepositoryTextLexicalBm25Settings = _DEFAULT_BM25_SETTINGS,
) -> RepositoryTextLexicalBm25RetrievalResult:
    """Rank positive content-term matches with Okapi BM25 under an explicit bound.

    For distinct normalized query terms, this uses
    ``ln(1 + (N - df + 0.5) / (df + 0.5)) * tf * (k1 + 1) /``
    ``(tf + k1 * (1 - b + b * document_length / average_document_length))``.
    """
    if maximum_results <= 0:
        msg = "Maximum BM25 result count must be positive."
        raise ValueError(msg)

    document_positions = {
        id(document_statistics): position
        for position, document_statistics in enumerate(
            index.corpus_statistics.document_statistics,
        )
    }
    document_frequency_by_term = {
        frequency.normalized_term: frequency.document_frequency
        for frequency in index.corpus_statistics.document_frequencies
    }
    postings_by_term = {
        term_postings.normalized_term: term_postings.postings
        for term_postings in index.term_postings
    }
    contributions_by_document: dict[
        int,
        list[RepositoryTextLexicalBm25TermContribution],
    ] = {}
    for term in query.normalized_terms:
        postings = postings_by_term.get(term)
        if postings is None:
            continue
        document_frequency = document_frequency_by_term[term]
        inverse_document_frequency = calculate_bm25_inverse_document_frequency(
            document_count=index.corpus_statistics.document_count,
            document_frequency=document_frequency,
        )
        for posting in postings:
            document_statistics = posting.document_statistics
            average_document_length = index.corpus_statistics.average_document_length
            contribution = calculate_bm25_term_contribution(
                term_frequency=posting.term_frequency.frequency,
                inverse_document_frequency=inverse_document_frequency,
                document_length=document_statistics.document_length,
                average_document_length=average_document_length,
                settings=settings,
            )
            contributions_by_document.setdefault(id(document_statistics), []).append(
                RepositoryTextLexicalBm25TermContribution(
                    normalized_term=term,
                    term_frequency=posting.term_frequency.frequency,
                    document_frequency=document_frequency,
                    inverse_document_frequency=inverse_document_frequency,
                    document_length=document_statistics.document_length,
                    average_document_length=average_document_length,
                    contribution=contribution,
                ),
            )

    ranked_documents = sorted(
        contributions_by_document.items(),
        key=lambda item: (
            -sum(contribution.contribution for contribution in item[1]),
            document_positions[item[0]],
        ),
    )
    matches = tuple(
        RepositoryTextLexicalBm25Match(
            document_statistics=index.corpus_statistics.document_statistics[
                document_positions[document_identity]
            ],
            score=sum(contribution.contribution for contribution in contributions),
            term_contributions=tuple(contributions),
            content_score=sum(
                contribution.contribution for contribution in contributions
            ),
        )
        for document_identity, contributions in ranked_documents
    )
    return RepositoryTextLexicalBm25RetrievalResult(
        query=query,
        index=index,
        settings=settings,
        maximum_results=maximum_results,
        matches=matches[:maximum_results],
    )


def retrieve_repository_text_documents_by_bm25(
    *,
    query: RepositoryTextLexicalQuery,
    index: RepositoryTextLexicalInvertedIndex,
    maximum_results: int,
    settings: RepositoryTextLexicalBm25Settings = _DEFAULT_BM25_SETTINGS,
) -> RepositoryTextLexicalBm25RetrievalResult:
    """Rank content and filename-stem BM25 evidence under one bounded result limit."""
    if maximum_results <= 0:
        msg = "Maximum BM25 result count must be positive."
        raise ValueError(msg)

    collection = index.corpus_statistics.collection_analysis.document_collection
    content_result = retrieve_repository_text_documents_by_content_bm25(
        query=query,
        index=index,
        maximum_results=max(1, len(collection.documents)),
        settings=settings,
    )
    filename_index = build_repository_text_filename_lexical_index(
        document_collection=collection,
    )
    filename_contributions = score_repository_text_filename_lexical_bm25(
        query=query,
        index=filename_index,
        settings=settings,
    )
    content_matches = {
        id(match.document_statistics.analysis.document): match
        for match in content_result.matches
    }
    document_statistics = {
        id(item.analysis.document): item
        for item in index.corpus_statistics.document_statistics
    }
    ranked_matches: list[tuple[int, RepositoryTextLexicalBm25Match]] = []
    for position, document in enumerate(collection.documents):
        document_identity = id(document)
        content_match = content_matches.get(document_identity)
        content_score = content_match.content_score if content_match else 0.0
        filename_terms = filename_contributions.get(document_identity, ())
        filename_score = sum(item.contribution for item in filename_terms)
        final_score = content_score + _FILENAME_BM25_WEIGHT * filename_score
        if final_score <= 0:
            continue
        ranked_matches.append(
            (
                position,
                RepositoryTextLexicalBm25Match(
                    document_statistics=document_statistics[document_identity],
                    score=final_score,
                    term_contributions=(
                        content_match.term_contributions if content_match else ()
                    ),
                    content_score=content_score,
                    filename_score=filename_score,
                    filename_weight=_FILENAME_BM25_WEIGHT,
                    weighted_filename_score=(_FILENAME_BM25_WEIGHT * filename_score),
                    filename_term_contributions=filename_terms,
                ),
            ),
        )
    ranked_matches.sort(key=lambda item: (-item[1].score, item[0]))
    return RepositoryTextLexicalBm25RetrievalResult(
        query=query,
        index=index,
        settings=settings,
        maximum_results=maximum_results,
        matches=tuple(match for _position, match in ranked_matches[:maximum_results]),
        filename_index=filename_index,
    )

def compose_lexical_structural_resource_evidence(  # noqa: C901, PLR0912
    snapshot: RepositorySnapshot,
    *,
    purpose: str,
    lexical_result: RepositoryTextLexicalBm25RetrievalResult,
    structural_result: PythonDirectStructuralRetrievalResult,
) -> LexicalStructuralResourceInventory:
    """Correlate native matches and supports under one caller-owned invocation.

    Address order is a neutral inventory order, not a relevance ranking. The
    lexical query remains mechanism input and need not equal the purpose.
    """
    if not purpose.strip():
        msg = "Resource evidence composition requires a nonempty purpose."
        raise ValueError(msg)
    if structural_result.snapshot_id != snapshot.id or (
        structural_result.request.purpose != purpose
    ):
        msg = "Structural retrieval differs from the composition snapshot or purpose."
        raise ValueError(msg)

    collection = (
        lexical_result.index.corpus_statistics.collection_analysis.document_collection
    )
    if collection.corpus.definition.discovery.repository_id != snapshot.repository_id:
        msg = "Lexical corpus belongs to another repository."
        raise ValueError(msg)
    if collection.corpus.resources != tuple(
        document.resource for document in collection.documents
    ):
        msg = "Lexical documents differ from their observed corpus."
        raise ValueError(msg)
    for document in collection.documents:
        if document.repository_id != snapshot.repository_id:
            msg = "Lexical document belongs to another repository."
            raise ValueError(msg)
        _require_snapshot_resource(snapshot, document.resource)

    statistics = lexical_result.index.corpus_statistics.document_statistics
    if tuple(item.analysis.document for item in statistics) != collection.documents:
        msg = "Lexical index statistics differ from its document collection."
        raise ValueError(msg)

    lexical_by_address: dict[
        RepositoryResourceAddress, tuple[int, RepositoryTextLexicalBm25Match],
    ] = {}
    for rank, match in enumerate(lexical_result.matches, start=1):
        if not any(match.document_statistics is item for item in statistics):
            msg = "Lexical match is absent from its retrieval index."
            raise ValueError(msg)
        address = match.document_statistics.analysis.document.resource.address
        previous = lexical_by_address.get(address)
        if previous is not None and previous[1] != match:
            msg = "Lexical retrieval has conflicting matches for one resource."
            raise ValueError(msg)
        if previous is None:
            lexical_by_address[address] = (rank, match)

    structural_by_address: dict[
        RepositoryResourceAddress, list[PythonDirectStructuralResourceEvidence],
    ] = {}
    structural_seen: dict[
        RepositoryResourceAddress, set[tuple[RepositoryResourceAddress, str, str]],
    ] = {}
    for candidate in structural_result.candidates:
        if candidate.snapshot_id != snapshot.id:
            msg = "Structural candidate belongs to another snapshot."
            raise ValueError(msg)
        snapshot.resource_at(candidate.resource_address)
        for support in candidate.supports:
            key = (support.seed_resource, support.direction, support.fact.identity)
            seen = structural_seen.setdefault(candidate.resource_address, set())
            if key not in seen:
                seen.add(key)
                structural_by_address.setdefault(candidate.resource_address, []).append(
                    support,
                )

    addresses = sorted(
        lexical_by_address.keys() | structural_by_address.keys(),
        key=str,
    )
    resources: list[LexicalStructuralResourceEntry] = []
    for address in addresses:
        lexical = lexical_by_address.get(address)
        resources.append(
            LexicalStructuralResourceEntry(
                snapshot_id=snapshot.id,
                resource=snapshot.resource_at(address),
                lexical_rank=lexical[0] if lexical is not None else None,
                lexical_match=lexical[1] if lexical is not None else None,
                structural_supports=tuple(structural_by_address.get(address, ())),
            ),
        )
    return LexicalStructuralResourceInventory(
        snapshot_id=snapshot.id,
        purpose=purpose,
        lexical_result=lexical_result,
        structural_result=structural_result,
        resources=tuple(resources),
    )


def _require_snapshot_resource(
    snapshot: RepositorySnapshot,
    resource: RepositoryResourceOccurrence,
) -> None:
    try:
        current = snapshot.resource_at(resource.address)
    except ValueError as error:
        msg = "Lexical corpus resource is absent from the supplied snapshot."
        raise ValueError(msg) from error
    if current != resource:
        msg = "Lexical corpus resource differs from the supplied snapshot."
        raise ValueError(msg)

from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar, Literal

from devtools.context.python.imports.relations import PythonResolvedModuleImportRelation
from devtools.context.python.modules.membership import PythonImmediatePackageMembership
from devtools.context.python.references.analysis import PythonFunctionReferenceKnowledge

if TYPE_CHECKING:
    from collections.abc import Sequence

    from devtools.context.repository.resource import (
        RepositoryResourceAddress,
        RepositoryResourceOccurrence,
    )
    from devtools.context.repository.snapshot import (
        RepositorySnapshot,
        RepositorySnapshotId,
    )

type PythonDirectStructuralFact = (
    PythonResolvedModuleImportRelation
    | PythonFunctionReferenceKnowledge
    | PythonImmediatePackageMembership
)
type PythonDirectStructuralDirection = Literal[
    "import-to-target",
    "import-to-source",
    "reference-to-definition",
    "definition-to-reference",
    "child-to-package",
    "package-to-child",
]


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralRetrievalRequest:
    """Carry one information purpose and caller-selected resource anchors."""

    purpose: str
    seed_resources: tuple[RepositoryResourceAddress, ...]

    def __post_init__(self) -> None:
        """Require an explicit purpose and a nonempty, distinct seed set."""
        if not self.purpose.strip():
            msg = "Direct structural retrieval requires a nonempty purpose."
            raise ValueError(msg)
        if not self.seed_resources or len(set(self.seed_resources)) != len(
            self.seed_resources,
        ):
            msg = "Direct structural retrieval requires distinct seed resources."
            raise ValueError(msg)


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralResourceEvidence:
    """Retain one seed, direction, and exact RI fact supporting a resource."""

    seed_resource: RepositoryResourceAddress
    direction: PythonDirectStructuralDirection
    fact: PythonDirectStructuralFact

    MECHANISM: ClassVar[str] = "direct-python-ri-resource-projection-v1"


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralResourceCandidate:
    """Group independent direct supports for one snapshot resource occurrence."""

    snapshot_id: RepositorySnapshotId
    resource_address: RepositoryResourceAddress
    supports: tuple[PythonDirectStructuralResourceEvidence, ...]


@dataclass(frozen=True, slots=True)
class PythonDirectStructuralRetrievalResult:
    """Retain the request, snapshot, and candidates in first-support order."""

    request: PythonDirectStructuralRetrievalRequest
    snapshot_id: RepositorySnapshotId
    candidates: tuple[PythonDirectStructuralResourceCandidate, ...]


def retrieve_python_direct_structural_resources(  # noqa: C901, PLR0912
    snapshot: RepositorySnapshot,
    *,
    request: PythonDirectStructuralRetrievalRequest,
    imports: Sequence[PythonResolvedModuleImportRelation] = (),
    references: Sequence[PythonFunctionReferenceKnowledge] = (),
    memberships: Sequence[PythonImmediatePackageMembership] = (),
) -> PythonDirectStructuralRetrievalResult:
    """Project supplied positive RI facts one relation away from each seed.

    Inputs are already-derived facts. Missing facts establish no negative claim;
    this operation neither derives relations nor selects or ranks candidates.
    """
    for seed in request.seed_resources:
        snapshot.resource_at(seed)

    pairs: list[
        tuple[
            RepositoryResourceAddress,
            RepositoryResourceAddress,
            PythonDirectStructuralDirection,
            PythonDirectStructuralDirection,
            PythonDirectStructuralFact,
        ]
    ] = []
    for import_fact in imports:
        if not isinstance(import_fact, PythonResolvedModuleImportRelation):
            msg = "Imports must contain resolved module import relations."
            raise TypeError(msg)
        _check_endpoint(
            snapshot, import_fact.source.snapshot_id, import_fact.source.resource,
        )
        _check_endpoint(
            snapshot, import_fact.target.snapshot_id, import_fact.target.resource,
        )
        pairs.append(
            (
                import_fact.source.resource.address,
                import_fact.target.resource.address,
                "import-to-target",
                "import-to-source",
                import_fact,
            ),
        )
    for reference_fact in references:
        if not isinstance(reference_fact, PythonFunctionReferenceKnowledge):
            msg = "References must contain qualified function reference knowledge."
            raise TypeError(msg)
        reference_source = reference_fact.occurrence
        definition = reference_fact.target_declaration.support
        _check_address(
            snapshot, reference_source.snapshot_id, reference_source.resource_address,
        )
        _check_address(snapshot, definition.snapshot_id, definition.resource_address)
        pairs.append(
            (
                reference_source.resource_address,
                definition.resource_address,
                "reference-to-definition",
                "definition-to-reference",
                reference_fact,
            ),
        )
    for membership_fact in memberships:
        if not isinstance(membership_fact, PythonImmediatePackageMembership):
            msg = "Memberships must contain immediate package membership facts."
            raise TypeError(msg)
        _check_endpoint(
            snapshot, membership_fact.child.snapshot_id, membership_fact.child.resource,
        )
        _check_endpoint(
            snapshot,
            membership_fact.package.snapshot_id,
            membership_fact.package.resource,
        )
        pairs.append(
            (
                membership_fact.child.resource.address,
                membership_fact.package.resource.address,
                "child-to-package",
                "package-to-child",
                membership_fact,
            ),
        )

    grouped: dict[
        RepositoryResourceAddress,
        list[PythonDirectStructuralResourceEvidence],
    ] = {}
    seen: set[
        tuple[RepositoryResourceAddress, PythonDirectStructuralDirection, str]
    ] = set()
    for seed in request.seed_resources:
        for source_address, target_address, forward, reverse, fact in pairs:
            if source_address == target_address:
                continue
            if seed == source_address:
                candidate, direction = target_address, forward
            elif seed == target_address:
                candidate, direction = source_address, reverse
            else:
                continue
            key = (seed, direction, fact.identity)
            if key not in seen:
                seen.add(key)
                grouped.setdefault(candidate, []).append(
                    PythonDirectStructuralResourceEvidence(seed, direction, fact),
                )
    return PythonDirectStructuralRetrievalResult(
        request=request,
        snapshot_id=snapshot.id,
        candidates=tuple(
            PythonDirectStructuralResourceCandidate(
                snapshot.id,
                address,
                tuple(supports),
            )
            for address, supports in grouped.items()
        ),
    )


def _check_endpoint(
    snapshot: RepositorySnapshot,
    snapshot_id: RepositorySnapshotId,
    resource: RepositoryResourceOccurrence,
) -> None:
    if snapshot_id != snapshot.id or snapshot.resource_at(resource.address) != resource:
        msg = "Structural fact endpoint does not belong to the supplied snapshot."
        raise ValueError(msg)


def _check_address(
    snapshot: RepositorySnapshot,
    snapshot_id: RepositorySnapshotId,
    address: RepositoryResourceAddress,
) -> None:
    if snapshot_id != snapshot.id:
        msg = "Structural fact endpoint does not belong to the supplied snapshot."
        raise ValueError(msg)
    snapshot.resource_at(address)

